<script lang="ts" module>


  import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";

  export type NavItem = {
    title: string;
    // this should be `Component` after @lucide/svelte updates types
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    iconName?: string;
    isActive?: boolean;
    items?: {
      title: string;
    }[];
    menuItems?: {
      id: string;
      title: string;
    }[];
    node: DynamicLayoutNode;
  };

</script>

<script lang="ts">
  import * as Collapsible from "$lib/components/ui/collapsible";
  import * as DropdownMenu from "$lib/components/ui/dropdown-menu";
  import * as Sidebar from "$lib/components/ui/sidebar";
  import * as Tooltip from "$lib/components/ui/tooltip";
  import ChevronRight from "@lucide/svelte/icons/chevron-right";
  import Plus from "@lucide/svelte/icons/plus";
  import { Ellipsis } from "$lib/components/ui/breadcrumb";
  import { useSidebar } from "$lib/components/ui/sidebar";
  import type { Snippet } from "svelte";

  import { preventDefault } from "svelte/legacy";
  import { base } from "$app/paths";
  import LucideIcon from "$lib/components/composites/lucide-svelte-icons/LucideIcon.svelte";

  let {
    items,
    onNewDashboard,
    menuItemClicked
  }: {
    items: NavItem[],
    onNewDashboard: () => void,
    menuItemClicked: (item: NavItem, menuItemId: string) => void
  } = $props();


  const sidebar = useSidebar();

  function menuItemClickHandler (item: NavItem, menuItemId: string) {
    // e.preventDefault();
    menuItemClicked(item, menuItemId);
  }
</script>

{#snippet MenuItem (navItem: NavItem, props: any = {}, afterLabel: Snippet|null = null)}
  <Sidebar.MenuButton
    {...props}
    class="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground group-data-[collapsible=icon]:!gap-1 {navItem.isActive ? 'active' : ''}"
  >


    {#if navItem.iconName}
      <Tooltip.Provider>
        <Tooltip.Root>
          <Tooltip.Trigger>
            <a href={base+'/dashboard/'+navItem.node.id}>
              <LucideIcon iconName={navItem.iconName} class="group-data-[collapsible=icon]:!size-11" />
            </a>
          </Tooltip.Trigger>
          <Tooltip.Content>
            <p>{navItem.title}</p>
          </Tooltip.Content>
        </Tooltip.Root>
      </Tooltip.Provider>

    {/if}
    <a href={base+'/dashboard/'+navItem.node.id} {...props} style="flex: 1" class="truncate">{navItem.title}</a>

    {#if afterLabel}
      {@render afterLabel()}
    {/if}
  </Sidebar.MenuButton>
{/snippet}

<Sidebar.Group>
  <Sidebar.GroupLabel>Dashboards</Sidebar.GroupLabel>
  <Sidebar.GroupAction onclick={onNewDashboard}>
    <Plus />
    <span class="sr-only">Add Project</span>
  </Sidebar.GroupAction>
  <Sidebar.Menu>
    {#each items as mainItem (mainItem.title)}
      {#if (mainItem.items?.length ?? 0) === 0}
        {#if (mainItem.menuItems?.length ?? 0) > 0}

          <Sidebar.MenuItem>
            {@render MenuItem(mainItem, {})}

            {#if mainItem.menuItems?.length}
              <DropdownMenu.Root>
                <DropdownMenu.Trigger>
                  {#snippet child ({ props })}
                    <Sidebar.MenuAction showOnHover {...props}>
                      <Ellipsis />
                      <span class="sr-only">More</span>
                    </Sidebar.MenuAction>
                  {/snippet}
                </DropdownMenu.Trigger>

                <DropdownMenu.Content
                  side={sidebar.isMobile ? "bottom" : "right"}
                  align={sidebar.isMobile ? "end" : "start"}
                  class="min-w-56 rounded-lg"
                >
                  {#each mainItem.menuItems as item (item.title)}
                    <DropdownMenu.Item closeOnSelect onSelect={() => menuItemClickHandler( mainItem,item.id)}>
                      {#snippet child ({ props })}
                        <a {...props}>{item.title}</a>
                      {/snippet}
                    </DropdownMenu.Item>
                  {/each}
                </DropdownMenu.Content>

              </DropdownMenu.Root>

            {/if}
          </Sidebar.MenuItem>
        {:else}

          <Sidebar.MenuItem>
            {@render MenuItem(mainItem)}
          </Sidebar.MenuItem>
        {/if}
      {:else}

        <Collapsible.Root open={mainItem.isActive} class="group/collapsible">
          {#snippet child ({ props })}
            <Sidebar.MenuItem {...props}>
              <Collapsible.Trigger>
                {#snippet child ({ props })}
                  <Sidebar.MenuButton {...props}>
                    {#snippet tooltipContent ()}
                      {mainItem.title}
                    {/snippet}
                    {#if mainItem.icon}
                      <mainItem.icon />
                    {/if}
                    <span>{mainItem.title}</span>
                    <ChevronRight
                      class="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90"
                    />
                  </Sidebar.MenuButton>
                {/snippet}
              </Collapsible.Trigger>
              <Collapsible.Content>
                {#if mainItem.items}
                  <Sidebar.MenuSub>
                    {#each mainItem.items as subItem (subItem.title)}
                      <Sidebar.MenuSubItem>
                        <Sidebar.MenuSubButton>
                          {#snippet child ({ props })}
                            <a {...props}>
                              <span>{subItem.title}</span>
                            </a>
                          {/snippet}
                        </Sidebar.MenuSubButton>
                      </Sidebar.MenuSubItem>
                    {/each}
                  </Sidebar.MenuSub>
                {/if}
              </Collapsible.Content>
            </Sidebar.MenuItem>
          {/snippet}
        </Collapsible.Root>
      {/if}
    {/each}
  </Sidebar.Menu>
</Sidebar.Group>

<style>
   :global(.active) {
      background-color: purple;
      color: var(--sidebar-accent-foreground);
   }
</style>
